using namespace std;

using ll = long long;

int main() {
    ll k, a, b;
    cin >> k >> a >> b;

    ll sum = 0;

    while (a >= k || b >= k) {
        bool moved = false;

        if (a >= k && a > b + 2) {
            a -= k;
            ++sum;
            moved = true;
        }

        if (b >= k && b > a + 2) {
            b -= k;
            ++sum;
            moved = true;
        }

        if (!moved) break;
    }

    cout << (sum == 0 ? -1 : sum);
    return 0;
}

